package ru.skfu.softwarestore.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orders") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Order { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Enumerated(EnumType.STRING) @Builder.Default @Column(nullable=false,length=20) private OrderStatus status=OrderStatus.CREATED; @Builder.Default @Column(nullable=false,precision=12,scale=2) private BigDecimal totalAmount=BigDecimal.ZERO; @Builder.Default @Column(nullable=false,length=10) private String currency="RUB"; @Builder.Default @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt=LocalDateTime.now(); @Builder.Default @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt=LocalDateTime.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) @Builder.Default private List<OrderItem> items=new ArrayList<>(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();} }
